  // Hillcrest is closed on weekends and on Friday 2026-12-25.
  assert.equal(nextOpenDay(branchById('hillcrest'), '2026-12-25'), '2026-12-28');
  // Riverside is closed on Thursday 2026-12-24 and Friday 2026-12-25, and open on Saturday.
  assert.equal(nextOpenDay(branchById('riverside'), '2026-12-24'), '2026-12-26');
});
