import { addDays, weekdayOf } from './dates.js';

/**
 * Tells whether a branch is open on a calendar date: not a closed weekday, not a holiday and not within
 * a multi-day closure (`closures`, both ends included; a branch without any has no such field).
 */
export function isOpenOn(branch, isoDate) {
  if (branch.closedWeekdays.includes(weekdayOf(isoDate))) return false;
  if (branch.holidays.includes(isoDate)) return false;
  return !(branch.closures ?? []).some(({ from, to }) => from <= isoDate && isoDate <= to);
}

/** Returns the first date on or after `isoDate` on which the branch is open. */
export function nextOpenDay(branch, isoDate) {
  let day = isoDate;
  while (!isOpenOn(branch, day)) day = addDays(day, 1);
  return day;
}
EOF
cat >> test/dates.test.js <<'EOF'

test('a branch is closed on every day of a closure, both ends included', () => {
  const renovating = { ...branchById('central'), closures: [{ from: '2027-02-01', to: '2027-02-14' }] };
  assert.equal(isOpenOn(renovating, '2027-01-31'), true);
  assert.equal(isOpenOn(renovating, '2027-02-01'), false);
  assert.equal(isOpenOn(renovating, '2027-02-10'), false);
  assert.equal(isOpenOn(renovating, '2027-02-14'), false);
  assert.equal(isOpenOn(renovating, '2027-02-15'), true);
});

test('the next open day skips a closure', () => {
  const renovating = { ...branchById('central'), closures: [{ from: '2027-02-01', to: '2027-02-14' }] };
  // 2027-02-15 is a Monday.
  assert.equal(nextOpenDay(renovating, '2027-02-03'), '2027-02-15');
});
EOF
